// netlify/functions/ncm-api/module/eapi_decrypt.js
var require_eapi_decrypt = __commonJS({
  "netlify/functions/ncm-api/module/eapi_decrypt.js"(exports2, module2) {
    var { eapiResDecrypt, eapiReqDecrypt } = require_crypto();
    var createOption = require_option();
    module2.exports = async (query, request) => {
      const hexString = query.hexString;
      const isReq = query.isReq != "false";
      if (!hexString) {
        return {
          status: 400,
          body: {
            code: 400,
            message: "hex string is required"
          }
        };
      }
      let pureHexString = hexString.replace(/\s/g, "");
      return {
        status: 200,
        body: {
          code: 200,
          data: isReq ? eapiReqDecrypt(pureHexString) : eapiResDecrypt(pureHexString)
        }
      };
    };
  }
});

